SET_31_CLEAN_QUESTIONS = [{'question': '‘அம்மா குழந்தைக்குச் சோறு ஊட்டினாள்’ – எவ்வகை வினை?', 'options': {'A': 'பிறவினை வாக்கியம்', 'B': 'தன்வினை வாக்கியம்', 'C': 'செய்வினை வாக்கியம்', 'D': 'செயப்பாட்டுவினை வாக்கியம்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'குழந்தை சோறு உண்டது தன்வினை; தாய் ஊட்டியதால் பிறவினை வாக்கியம் ஆகும்.', 'topic': 'இலக்கணம் - தன்வினை பிறவினை'}, {'question': '‘வள்ளுவரால் திருக்குறள் இயற்றப்பட்டது’ – இத்தொடர் :', 'options': {'A': 'செயப்பாட்டுவினைத் தொடர்', 'B': 'செய்வினைத் தொடர்', 'C': 'தன்வினைத் தொடர்', 'D': 'பிறவினைத் தொடர்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': "'ஆல்' வேற்றுமை உருபும் 'பட்டது' துணைவினையும் பெற்று வந்ததால் செயப்பாட்டுவினை.", 'topic': 'இலக்கணம் - செய்வினை செயப்பாட்டுவினை'}, {'question': "விடைக்கேற்ற வினாவைத் தேர்ந்தெடுக்க : 'பாரதியார் பெண்களுக்காகப் பாடுபட்டார்.'", 'options': {'A': 'பாரதியார் யாருக்காகப் பாடுபட்டார்?', 'B': 'பாரதியார் யார்?', 'C': 'பெண்கள் யார்?', 'D': 'பாரதியார் கவிதைகள் யாவை?', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': "'யாருக்காகப் பாடுபட்டார்?' என்ற வினாவிற்கு 'பெண்களுக்காகப் பாடுபட்டார்' என்பது பொருத்தமானது.", 'topic': 'இலக்கணம் - விடைக்கேற்ற வினா'}, {'question': "விடைக்கேற்ற வினாவைத் தேர்ந்தெடுக்க : 'சென்னை தமிழ்நாட்டின் தலைநகரம் ஆகும்.'", 'options': {'A': 'தமிழ்நாட்டின் தலைநகரம் எது?', 'B': 'சென்னை எங்குள்ளது?', 'C': 'தலைநகரங்கள் எத்தனை?', 'D': 'சென்னை எப்போது உருவானது?', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': "தலைநகரை வினவுவதற்கு 'தமிழ்நாட்டின் தலைநகரம் எது?' என்பதே பொருத்தமான வினா.", 'topic': 'இலக்கணம் - விடைக்கேற்ற வினா'}, {'question': '‘வந்தான்’ – என்ற சொல்லின் வேர்ச்சொல்லைக் காண்க.', 'options': {'A': 'வா', 'B': 'வந்து', 'C': 'வந்த', 'D': 'வருகை', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': "வந்தான் என்பதன் ஏவல் மூலப்பகுதி 'வா' ஆகும்.", 'topic': 'இலக்கணம் - வேர்ச்சொல்'}, {'question': '‘கற்றான்’ – இச்சொல்லின் வேர்ச்சொல்லைத் தேர்க :', 'options': {'A': 'கல்', 'B': 'கற்று', 'C': 'கற்ற', 'D': 'கற்றல்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': "கற்றான் என்ற வினைமுற்றின் வேர்ச்சொல் அல்லது பகுதி 'கல்' என்ற ஏவல் வினையாகும்.", 'topic': 'இலக்கணம் - வேர்ச்சொல்'}, {'question': '‘நட’ என்ற வேர்ச்சொல்லின் தொழிற்பெயர் யாது?', 'options': {'A': 'நடத்தல்', 'B': 'நடந்த', 'C': 'நடந்து', 'D': 'நடந்தவர்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': "'தல்' விகுதி பெற்று வரும் 'நடத்தல்' தொழிற்பெயர் ஆகும்.", 'topic': 'இலக்கணம் - தொழிற்பெயர்'}, {'question': '‘பாடிய’ – என்பது எவ்வகை எச்சம்?', 'options': {'A': 'பெயரெச்சம்', 'B': 'வினையெச்சம்', 'C': 'வினைமுற்று', 'D': 'தொழிற்பெயர்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': "'அ' விகுதி பெற்றுப் பெயர்ச்சொல்லைக் கொண்டு முடிவதற்கு நிற்கும் எச்சம் பெயரெச்சம் (பாடிய பறவை).", 'topic': 'இலக்கணம் - பெயரெச்சம்'}, {'question': 'அகர வரிசைப்படி அமைந்த சொற்களைத் தேர்க (க-வரிசை உயிர்மெய்) :', 'options': {'A': 'கனி, காடு, கிளி, கூடை', 'B': 'காடு, கனி, கூடை, கிளி', 'C': 'கூடை, கிளி, காடு, கனி', 'D': 'கிளி, கூடை, கனி, காடு', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'க (அ) -> கா (ஆ) -> கி (இ) -> கூ (ஊ). சரியான அகரவரிசை: கனி, காடு, கிளி, கூடை.', 'topic': 'இலக்கணம் - அகரவரிசை'}, {'question': 'அகர வரிசைப்படி சொற்களைச் சீர்செய்க : தாகம், தம்பி, திரு, துளிர்', 'options': {'A': 'தம்பி, தாகம், திரு, துளிர்', 'B': 'தாகம், தம்பி, துளிர், திரு', 'C': 'திரு, துளிர், தம்பி, தாகம்', 'D': 'துளிர், திரு, தாகம், தம்பி', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'த -> தா -> தி -> து வரிசை.', 'topic': 'இலக்கணம் - அகரவரிசை'}, {'question': 'ஒலி வேறுபாடறிந்து சரியான பொருளைத் தேர்க : அலை - அழை', 'options': {'A': 'கடலலை - கூப்பிடுதல்', 'B': 'கூப்பிடுதல் - கடலலை', 'C': 'புற்று - கடலலை', 'D': 'கடலலை - புற்று', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'அலை = கடலின் திரை/அலை; அழை = கூப்பிடுதல்.', 'topic': 'இலக்கணம் - மயங்கொலி வேறுபாடு'}, {'question': 'ஒலி வேறுபாடறிந்து சரியான பொருளைத் தேர்க : ‘திணை – தினை’', 'options': {'A': 'ஒழுக்கம் / நிலம் – தானிய வகை', 'B': 'தானிய வகை – ஒழுக்கம்', 'C': 'உணவு – பாடல்', 'D': 'காடு – கடல்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'திணை (ணகரம்) என்பது ஒழுக்கம், நிலம் மற்றும் குடிப் பிரிவைக் குறிக்கும்; தினை (நகரம்) சிறுதானியத்தைக் குறிக்கும்.', 'topic': 'இலக்கணம் - மயங்கொலி வேறுபாடு'}, {'question': 'ஓரெழுத்து ஒரு மொழிக்குரிய சரியான பொருளைத் தேர்க : ‘கோ’', 'options': {'A': 'அரசன் / தலைவன்', 'B': 'பசு', 'C': 'கோயில்', 'D': 'மலை', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': "நன்னூல் காட்டும் ஓரெழுத்து ஒருமொழியில் 'கோ' என்பது அரசன், இறைவன் அல்லது தலைவனைக் குறிக்கும்.", 'topic': 'இலக்கணம் - ஓரெழுத்து ஒருமொழி'}, {'question': "ஓரெழுத்து ஒரு மொழிக்குரிய சரியான பொருளைத் தேர்க : 'பா'", 'options': {'A': 'பாடல் (செய்யுள்)', 'B': 'மரம்', 'C': 'மண்', 'D': 'காற்று', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': "'பா' என்பது பாடல், செய்யுள், அழகு ஆகியவற்றைக் குறிக்கும்.", 'topic': 'இலக்கணம் - ஓரெழுத்து ஒருமொழி'}, {'question': 'பிரித்தெழுதுக : ‘அருந்தமிழ்’', 'options': {'A': 'அருமை + தமிழ்', 'B': 'அரும் + தமிழ்', 'C': 'அரு + தமிழ்', 'D': 'அருள் + தமிழ்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': "ஈறுபோதல் விதியால் 'மை' விகுதி கெட்டு அருமை + தமிழ் = அருந்தமிழ் என்றானது.", 'topic': 'இலக்கணம் - பிரித்தெழுதுக'}, {'question': 'பிரித்தெழுதுக : ‘இன்னுரை’', 'options': {'A': 'இனிமை + உரை', 'B': 'இன் + உரை', 'C': 'இனிய + உரை', 'D': 'இனி + உரை', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': "ஈறுபோதல் விதியால் 'மை' கெட்டு, இணையவும் விதியால் ன் இரட்டித்து இனிமை + உரை = இன்னுரை என்றானது.", 'topic': 'இலக்கணம் - பிரித்தெழுதுக'}, {'question': 'சேர்த்தெழுதுக : ‘மண் + குடம்’', 'options': {'A': 'மட்குடம்', 'B': 'மண்குடம்', 'C': 'மண்ண்குடம்', 'D': 'மண்குடம்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'ணகார ஈற்று நிலைமொழி முன் வல்லினம் வரின் ணகரம் டகரமாகத் திரியும். எனவே மண் + குடம் = மட்குடம்.', 'topic': 'இலக்கணம் - புணர்ச்சி'}, {'question': 'பண்புத்தொகைகளுள் பொருந்தாச் சொல்லைக் கண்டறிக :', 'options': {'A': 'செந்தாமரை', 'B': 'வெண்குடை', 'C': 'வட்டப்பலகை', 'D': 'கைவாள்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'D', 'explanation': 'கைவாள் என்பது மூன்றாம் வேற்றுமை உருபும் பயனும் உடன் தொக்க தொகை (கையின்கண் வாள்); மற்ற மூன்றும் பண்புத்தொகைகள்.', 'topic': 'இலக்கணம் - பொருந்தாச் சொல்'}, {'question': 'சந்திப் பிழையற்ற தொடரைக் கண்டறிக (இரண்டாம் வேற்றுமை விரி) :', 'options': {'A': 'அவர் பாடத்தை படித்தார்', 'B': 'அவர் பாடத்தைப் படித்தார்', 'C': 'அவர் பாடத்தை படிப்பித்தார்', 'D': 'அவர் பாடம் படித்தார்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'B', 'explanation': 'இரண்டாம் வேற்றுமை உருபு (ஐ) வெளிப்பட்டு வரும் தொடர்களின் பின் வல்லினம் மிகும் (பாடத்தை + படித்தார் = பாடத்தைப் படித்தார்).', 'topic': 'இலக்கணம் - சந்திப்பிழை நீக்குதல்'}, {'question': 'ஒருமை - பன்மை பிழையற்ற தொடர் எது? (அவை / அது வினைகாட்டி)', 'options': {'A': 'பறவைகள் வானில் பறந்தது', 'B': 'பறவைகள் வானில் பறந்தன', 'C': 'பறவைகள் வானில் பறந்தாள்', 'D': 'பறவைகள் வானில் பறந்தான்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'B', 'explanation': "பறவைகள் என்பது அஃறிணைப் பன்மை; அதற்குரிய பன்மை வினைமுற்று 'பறந்தன' என்பதாகும்.", 'topic': 'இலக்கணம் - பிழை நீக்குதல்'}, {'question': 'யானை பிளிறும் என்பது எவ்வகை மரபு?', 'options': {'A': 'ஒலி மரபு', 'B': 'வினை மரபு', 'C': 'இளமை மரபு', 'D': 'தொகை மரபு', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': "யானையின் குரலை 'பிளிறும்' எனக் கூறுவது மரபு.", 'topic': 'இலக்கணம் - மரபுச் சொற்கள்'}, {'question': 'நாயின் இளமைப் பெயர் யாது?', 'options': {'A': 'குட்டி (நாய்க்குட்டி)', 'B': 'கன்று', 'C': 'பிள்ளை', 'D': 'குருளை', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'நாயின் இளமைப் பெயர் நாய்க்குட்டி ஆகும்.', 'topic': 'இலக்கணம் - இளமைப் பெயர்கள்'}, {'question': 'மரபுப் பிழையற்ற தொடரைத் தேர்க (யானையின் இளமைப் பெயர்) :', 'options': {'A': 'யானைக் கன்று காட்டில் கூட்டமாகச் சென்றது', 'B': 'யானைக் குட்டி காட்டில் கூட்டமாகச் சென்றது', 'C': 'யானைப் பிள்ளை காட்டில் கூட்டமாகச் சென்றது', 'D': 'யானைப் பறழ் காட்டில் கூட்டமாகச் சென்றது', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': "யானை, பசு, எருமை ஆகியவற்றின் இளமைப் பெயர் 'கன்று' ஆகும் (யானைக் கன்று).", 'topic': 'இலக்கணம் - மரபு வழு'}, {'question': 'ஆங்கிலச் சொல்லுக்கு நேரான தமிழ்ச் சொல் : ‘Platform’', 'options': {'A': 'நடைமேடை', 'B': 'விமானத்தளம்', 'C': 'படிக்கட்டு', 'D': 'தளம்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': "ரயில்வே அல்லது பேருந்து நிலைய நடைமேடைக்கு நேரான கலைச்சொல் 'நடைமேடை' ஆகும்.", 'topic': 'இலக்கணம் - கலைச்சொல்'}, {'question': 'ஆங்கிலச் சொல்லுக்கு நேரான தமிழ்ச் சொல் : ‘Document’', 'options': {'A': 'ஆவணம்', 'B': 'சான்றிதழ்', 'C': 'கடிதம்', 'D': 'புத்தகம்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': "Document என்பதன் நேரான கலைச்சொல் 'ஆவணம்' (Certificate = சான்றிதழ்).", 'topic': 'இலக்கணம் - கலைச்சொல்'}, {'question': '‘நீர்மேல் எழுத்து போல’ – இவ்வுவமை உணர்த்தும் பொருள் யாது?', 'options': {'A': 'நிலையற்ற தன்மை', 'B': 'நிலையான தன்மை', 'C': 'அழகு', 'D': 'வேகம்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'நீரின் மேல் எழுதும் எழுத்து உடனே மறைந்து போவது போல, நிலையற்ற அழியக்கூடிய பொருளைக் குறிக்கும்.', 'topic': 'இலக்கணம் - உவமை பொருள்'}, {'question': '‘நகமும் சதையும் போல’ – உவமை உணர்த்தும் பொருள் :', 'options': {'A': 'பிரிவின்றி இணைந்திருத்தல்', 'B': 'பகைமை', 'C': 'கோபம்', 'D': 'மகிழ்ச்சி', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'பிரிக்க முடியாத நெருங்கிய நட்பைக் குறிக்கும் உவமை.', 'topic': 'இலக்கணம் - உவமை விளக்கம்'}, {'question': '‘அத்தி பூத்தது போல’ – இவ்வுவமை உணர்த்தும் பொருள் யாது?', 'options': {'A': 'அரிதான நிகழ்வு', 'B': 'எளிதான நிகழ்வு', 'C': 'மகிழ்ச்சியான நிகழ்வு', 'D': 'சோகமான நிகழ்வு', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'அத்திமரம் பூப்பது வெளியில் தெரியாத அரிய செயல்; எனவே எப்போதாவது நிகழும் அரிய நிகழ்வைக் குறிக்கும்.', 'topic': 'இலக்கணம் - உவமை பொருள்'}, {'question': "இலக்கணக் குறிப்புத் தருக : 'தேன்மொழி'", 'options': {'A': 'உவமைத்தொகை', 'B': 'உருவகம்', 'C': 'பண்புத்தொகை', 'D': 'வினைத்தொகை', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'தேன் போன்ற மொழி என உவம உருபு மறைந்து வந்ததால் உவமைத்தொகை.', 'topic': 'இலக்கணம் - இலக்கணக் குறிப்பு'}, {'question': 'விடைக்கேற்ற வினாவைத் தேர்ந்தெடுக்க : ‘திருவள்ளுவர் மயிலாப்பூரில் வாழ்ந்தார்.’', 'options': {'A': 'திருவள்ளுவர் எங்கு வாழ்ந்தார்?', 'B': 'திருவள்ளுவர் எப்போது வாழ்ந்தார்?', 'C': 'மயிலாப்பூரில் யார் பிறந்தார்?', 'D': 'திருவள்ளுவரின் ஊர் யாது?', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': "இடத்தைக் குறிக்கும் செய்திக்கு 'எங்கு' என்ற வினாச்சொல் அமைவதே சரியான அமைப்பாகும்.", 'topic': 'இலக்கணம் - வினா அமைப்பு'}, {'question': '‘தாய் தன் குழந்தைக்குப் பாலூட்டினாள்’ – எவ்வகை வாக்கியம்?', 'options': {'A': 'பிறவினை வாக்கியம்', 'B': 'தன்வினை வாக்கியம்', 'C': 'செயப்பாட்டுவினை வாக்கியம்', 'D': 'உணர்ச்சி வாக்கியம்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'குழந்தை பால் உண்டது தன்வினை; தாய் பாலூட்டினாள் (உண்ணச் செய்தாள்) என்பது பிறவினை வாக்கியம்.', 'topic': 'இலக்கணம் - தன்வினை பிறவினை'}, {'question': '‘அந்தோ! பரிதாபம்!’ – எவ்வகை வாக்கியம்?', 'options': {'A': 'உணர்ச்சி வாக்கியம்', 'B': 'செய்தி வாக்கியம்', 'C': 'வினா வாக்கியம்', 'D': 'விழைவு வாக்கியம்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'வியப்பு, அவலம், மகிழ்ச்சி போன்ற உள்ளத்து உணர்வுகளை வெளிப்படுத்தும் தொடர் உணர்ச்சி வாக்கியம் எனப்படும்.', 'topic': 'இலக்கணம் - தொடர்வகை'}, {'question': '‘கபிலர் குறிஞ்சிப்பாட்டை இயற்றினார்’ – இதனைச் செயப்பாட்டுவினைத் தொடராக மாற்றுக :', 'options': {'A': 'குறிஞ்சிப்பாட்டு கபிலரால் இயற்றப்பட்டது', 'B': 'கபிலரால் குறிஞ்சிப்பாட்டு பாடப்பட்டது', 'C': 'குறிஞ்சிப்பாட்டை கபிலர் இயற்றவில்லை', 'D': 'கபிலர் குறிஞ்சிப்பாட்டு இயற்றினாரா?', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': "செயப்படுபொருளான 'குறிஞ்சிப்பாட்டு' எழுவாயாகி, மூன்றாம் வேற்றுமை உருபும் (ஆல்), 'பட்டது' துணைவினையும் ஏற்பது செயப்பாட்டுவினை.", 'topic': 'இலக்கணம் - செய்வினை செயப்பாட்டுவினை'}, {'question': '‘அவன் தானாகவே வந்தான்’ – இத்தொடர் எவ்வகை வினை?', 'options': {'A': 'தன்வினைத் தொடர்', 'B': 'பிறவினைத் தொடர்', 'C': 'செயப்பாட்டுவினைத் தொடர்', 'D': 'எதிர்மறைத் தொடர்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'எழுவாய் செயலைத் தானே செய்வதால் இது தன்வினைத் தொடர் ஆகும்.', 'topic': 'இலக்கணம் - தன்வினை பிறவினை'}, {'question': 'செய்யுளின் அடிகளிலோ சீர்களிலோ இறுதி எழுத்தோ சொல்லோ ஒன்றி வருவது :', 'options': {'A': 'இயைபு', 'B': 'மோனை', 'C': 'எதுகை', 'D': 'முரண்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'அடிதோறும் அல்லது சீர்தோறும் இறுதி எழுத்தோ அசையோ சொல்லோ ஒன்றி அமைவது இயைபுத் தொடை எனப்படும்.', 'topic': 'இலக்கணம் - எதுகை மோனை'}, {'question': 'சொற்களை ஒழுங்குபடுத்தி சரியான சொற்றொடராக்குக (ஒழுக்கத்தின் மேன்மை) :', 'options': {'A': 'ஒழுக்கம் விழுப்பம் தரலான் ஒழுக்கம் உயிரினும் ஓம்பப் படும்', 'B': 'விழுப்பம் தரலான் ஒழுக்கம் உயிரினும் ஓம்பப் படும் ஒழுக்கம்', 'C': 'உயிரினும் ஓம்பப் படும் ஒழுக்கம் விழுப்பம் தரலான் ஒழுக்கம்', 'D': 'தரலான் விழுப்பம் ஒழுக்கம் உயிரினும் ஓம்பப் படும் ஒழுக்கம்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': "'ஒழுக்கம் விழுப்பம் தரலான் ஒழுக்கம் உயிரினும் ஓம்பப் படும்' என்பது திருக்குறளின் நேரான சீர் அமைப்பாகும்.", 'topic': 'இலக்கணம் - சொற்றொடர் அமைப்பு'}, {'question': '‘வைகை’ – எவ்வகைப் பெயர்ச்சொல்?', 'options': {'A': 'இடப்பெயர்', 'B': 'பொருட்பெயர்', 'C': 'காலப்பெயர்', 'D': 'தொழிற்பெயர்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'வைகை என்பது ஓடும் ஆற்றின் இடத்தைக் குறிக்கும் இடப்பெயர் ஆகும்.', 'topic': 'இலக்கணம் - பெயர்ச்சொல்'}, {'question': '‘இனிமை’ – எவ்வகைப் பெயர்ச்சொல்?', 'options': {'A': 'பண்புப்பெயர்', 'B': 'தொழிற்பெயர்', 'C': 'சினைப்பெயர்', 'D': 'பொருட்பெயர்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': "சுவை அல்லது மனநிலைப் பண்பை உணர்த்தி 'மை' விகுதி பெற்று வருவதால் பண்புப்பெயர்.", 'topic': 'இலக்கணம் - பெயர்ச்சொல்'}, {'question': '‘வாழ்க’ – இலக்கணக் குறிப்பு தருக.', 'options': {'A': 'வியங்கோள் வினைமுற்று', 'B': 'ஏவல் வினைமுற்று', 'C': 'பெயரெச்சம்', 'D': 'வினையெச்சம்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': "'க' விகுதி பெற்று வாழ்த்துதல் பொருளில் வரும் வினை வியங்கோள் வினைமுற்று.", 'topic': 'இலக்கணம் - வியங்கோள் வினைமுற்று'}, {'question': '‘வாழ்க வாழ்க’ – இலக்கணக் குறிப்பு தருக.', 'options': {'A': 'அடுக்குத்தொடர்', 'B': 'இரட்டைக்கிளவி', 'C': 'வினைத்தொகை', 'D': 'உரிச்சொற்றொடர்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'பிரித்தால் தனித்துப் பொருள் தருமாறு இரண்டு முறை அடுக்கி வந்ததால் இது அடுக்குத்தொடர் ஆகும்.', 'topic': 'இலக்கணம் - அடுக்குத்தொடர்'}, {'question': 'திருக்குறளில் உள்ள மொத்த அதிகாரங்கள் மற்றும் குறட்பாக்களின் எண்ணிக்கை யாது?', 'options': {'A': '133 அதிகாரங்கள், 1330 குறட்பாக்கள்', 'B': '130 அதிகாரங்கள், 1300 குறட்பாக்கள்', 'C': '120 அதிகாரங்கள், 1200 குறட்பாக்கள்', 'D': '140 அதிகாரங்கள், 1400 குறட்பாக்கள்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'திருக்குறளில் அதிகாரத்திற்குப் பத்துக் குறட்பாக்கள் வீதம் 133 அதிகாரங்களில் 1330 குறள்கள் உள்ளன.', 'topic': 'இலக்கியம் - திருக்குறள்'}, {'question': 'திருக்குறளில் உள்ள மொத்த அதிகாரங்கள் எத்தனை?', 'options': {'A': '133', 'B': '1330', 'C': '100', 'D': '120', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'திருக்குறளில் 133 அதிகாரங்கள் உள்ளன.', 'topic': 'இலக்கியம் - திருக்குறள்'}, {'question': 'திருக்குறளுக்கு அமைந்த சிறந்த உரையாகப் போற்றப்படுவது யாருடைய உரை?', 'options': {'A': 'பரிமேலழகர்', 'B': 'மணக்குடவர்', 'C': 'காலிங்கர்', 'D': 'பரிதியார்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'பழைய பதின்மருள் பரிமேலழகரின் உரையே தலைசிறந்த உரையாகப் போற்றப்படுகிறது.', 'topic': 'இலக்கியம் - திருக்குறள் உரையாசிரியர்கள்'}, {'question': 'நான்மணிக்கடிகையில் உள்ள மொத்தப் பாடல்களின் எண்ணிக்கை யாது?', 'options': {'A': '104 பாடல்கள்', 'B': '100 பாடல்கள்', 'C': '102 பாடல்கள்', 'D': '106 பாடல்கள்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'கடவுள் வாழ்த்து இரண்டு பாடல்களுடன் சேர்த்து நான்மணிக்கடிகையில் மொத்தம் 104 வெண்பாக்கள் உள்ளன.', 'topic': 'இலக்கியம் - நான்மணிக்கடிகை'}, {'question': '‘பழமொழி நானூறு’ நூலின் ஆசிரியர் எந்தச் சமயத்தைச் சார்ந்தவர்?', 'options': {'A': 'சமண சமயம்', 'B': 'பௌத்த சமயம்', 'C': 'சைவ சமயம்', 'D': 'வைணவ சமயம்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'முன்றுறை அரையனார் தம் கடவுள் வாழ்த்தில் அருக தேவனை வணங்குவதால் அவர் சமண சமயத்தைச் சார்ந்தவர் என அறிகிறோம்.', 'topic': 'இலக்கியம் - அறநூல்கள்'}, {'question': 'திரிகடுகம் நூலில் உள்ள மொத்த வெண்பாக்களின் எண்ணிக்கை யாது?', 'options': {'A': '100 வெண்பாக்கள்', 'B': '104 வெண்பாக்கள்', 'C': '102 வெண்பாக்கள்', 'D': '90 வெண்பாக்கள்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'நல்லாதனார் இயற்றிய திரிகடுகத்தில் கடவுள் வாழ்த்து நீங்கலாக 100 வெண்பாக்கள் உள்ளன.', 'topic': 'இலக்கியம் - திரிகடுகம்'}, {'question': '‘முதுமொழிக்காஞ்சி’ நூலின் வேறு பெயர் யாது?', 'options': {'A': 'அறவுரைக்கோவை', 'B': 'வேளாண் வேதம்', 'C': 'நாலடி நானூறு', 'D': 'பழமொழி', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': "மதுரை கூடலூர்கிழார் இயற்றிய முதுமொழிக்காஞ்சி 'அறவுரைக்கோவை' எனவும் வழங்கப்படுகிறது.", 'topic': 'இலக்கியம் - முதுமொழிக்காஞ்சி'}, {'question': '‘நாலும் இரண்டும் சொல்லுக்குறுதி’ – இதில் நாலும் இரண்டும் முறையே எவற்றைக் குறிக்கும்?', 'options': {'A': 'நாலடியார், திருக்குறள்', 'B': 'நான்மணிக்கடிகை, திருக்குறள்', 'C': 'நாலடியார், திரிகடுகம்', 'D': 'திரிகடுகம், திருக்குறள்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'நான்கு அடிகளையுடைய நாலடியாரையும் இரண்டு அடிகளையுடைய திருக்குறளையும் குறிக்கும் பழமொழி.', 'topic': 'இலக்கியம் - பதினெண்கீழ்க்கணக்கு'}, {'question': 'கண்ணகியின் சிலம்பில் இருந்தவை எவை?', 'options': {'A': 'மாணிக்கப் பரல்கள்', 'B': 'முத்துப் பரல்கள்', 'C': 'வைரப் பரல்கள்', 'D': 'பவளப் பரல்கள்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'கண்ணகியின் காற்சிலம்பில் மாணிக்கப் பரல்கள் ஒலித்தன.', 'topic': 'இலக்கியம் - சிலப்பதிகாரம்'}, {'question': 'சிலப்பதிகாரத்தை இயற்றியவர் யார்?', 'options': {'A': 'இளங்கோவடிகள்', 'B': 'சீத்தலைச் சாத்தனார்', 'C': 'திருத்தக்கதேவர்', 'D': 'கம்பர்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'சேர இளவரசரான இளங்கோவடிகள் சிலப்பதிகாரத்தை இயற்றினார்.', 'topic': 'இலக்கியம் - சிலப்பதிகாரம்'}, {'question': 'மணிமேகலையின் தந்தை யார்?', 'options': {'A': 'கோவலன்', 'B': 'மாசாத்துவான்', 'C': 'மாநாயக்கன்', 'D': 'செங்குட்டுவன்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'கோவலன் மற்றும் மாதவியின் மகளே மணிமேகலை.', 'topic': 'இலக்கியம் - மணிமேகலை'}, {'question': 'மணிமேகலைக்குப் பாத்திரம் வழங்கிய பொய்கை எது?', 'options': {'A': 'கோமுகிப் பொய்கை', 'B': 'சரவணப் பொய்கை', 'C': 'தாமரைப் பொய்கை', 'D': 'கமலாலயப் பொய்கை', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'மணிபல்லவத் தீவில் அமைந்துள்ள கோமுகிப் பொய்கையில் அமுதசுரபி வெளிப்பட்டது.', 'topic': 'இலக்கியம் - மணிமேகலை'}, {'question': 'சீவகசிந்தாமணியை இயற்றியவர் யார்?', 'options': {'A': 'திருத்தக்கதேவர்', 'B': 'தோலாமொழித்தேவர்', 'C': 'கம்பர்', 'D': 'சீத்தலைச் சாத்தனார்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'திருத்தக்கதேவர் விருத்தப்பாவால் சீவகசிந்தாமணியை இயற்றினார்.', 'topic': 'இலக்கியம் - சீவகசிந்தாமணி'}, {'question': 'சிலப்பதிகாரத்தின் மூன்று உண்மைகளுள் ‘அரசியல் பிழைத்தோர்க்கு அறங்கூற்றாகும்’ என்பது எந்தக் காண்டத்தில் உணர்த்தப்படுகிறது?', 'options': {'A': 'மதுரைக் காண்டம்', 'B': 'புகார்க் காண்டம்', 'C': 'வஞ்சிக் காண்டம்', 'D': 'மூன்று காண்டங்களிலும்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'பாண்டிய நெடுஞ்செழியன் நீதி தவறியதற்காக உயிர் துறந்த நிகழ்வு மதுரைக் காண்டத்தில் இடம்பெற்று இந்த உண்மையை விளக்குகிறது.', 'topic': 'இலக்கியம் - சிலப்பதிகாரம்'}, {'question': 'கம்பராமாயணத்தை இயற்றியவர் யார்?', 'options': {'A': 'கம்பர்', 'B': 'புகழேந்தி', 'C': 'ஒட்டக்கூத்தர்', 'D': 'செயங்கொண்டார்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'வால்மீகி இராமாயணத்தைத் தழுவி கம்பநாடகம் இயற்றியவர் கம்பர்.', 'topic': 'இலக்கியம் - கம்பராமாயணம்'}, {'question': 'கம்பராமாயணத்தில் குகன் எந்த நிலத்தின் தலைவன்?', 'options': {'A': 'நெய்தல் / குறிஞ்சி (கங்கை வேடர் தலைவன்)', 'B': 'பாலை நிலம்', 'C': 'மருத நிலம்', 'D': 'முல்லை நிலம்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'கங்கை நதிக்கரையில் அமைந்துள்ள சிருங்கிபேரபுரத்து வேடர் தலைவன் குகன்.', 'topic': 'இலக்கியம் - கம்பராமாயணம்'}, {'question': 'அகநானூற்றில் ‘மணிமிடை பவளம்’ பகுதியில் உள்ள பாடல்களின் எண்ணிக்கை யாது?', 'options': {'A': '180 பாடல்கள்', 'B': '120 பாடல்கள்', 'C': '100 பாடல்கள்', 'D': '300 பாடல்கள்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'களிற்றியானை நிரை (1-120), மணிமிடை பவளம் (121-300: 180 பாடல்கள்), நித்திலக் கோவை (301-400: 100 பாடல்கள்).', 'topic': 'இலக்கியம் - அகநானூறு'}, {'question': '‘யாயும் ஞாயும் யாராகியரோ எந்தையும் நுந்தையும் எம்முறைக் கேளிர்’ – என்று தொடங்கும் பாடலை இயற்றியவர் யார்?', 'options': {'A': 'செம்புலப் பெயனீரார்', 'B': 'கபிலர்', 'C': 'பரணர்', 'D': 'ஔவையார்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'குறுந்தொகையின் நாற்பதாவது பாடலான இப்பாடலை இயற்றியவர் செம்புலப் பெயனீரார் ஆவார்.', 'topic': 'இலக்கியம் - குறுந்தொகை'}, {'question': 'எட்டுத்தொகை நூல்களுள் ‘பண்ணோடு பாடப்பட்ட’ இசைப்பாடல் நூல் எது?', 'options': {'A': 'பரிபாடல்', 'B': 'நற்றிணை', 'C': 'குறுந்தொகை', 'D': 'பதிற்றுப்பத்து', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'பாடலின் முடிவில் பண்ணும் இசையமைத்த யாழாசிரியரின் பெயரும் குறிக்கப்பெறும் ஒரே சங்க நூல் பரிபாடல் ஆகும்.', 'topic': 'இலக்கியம் - எட்டுத்தொகை'}, {'question': "அகநானூற்றின் மூன்று பிரிவுகளுள் 'களிற்றியானை நிரை' பகுதியில் உள்ள பாடல்கள் எத்தனை?", 'options': {'A': '120', 'B': '180', 'C': '100', 'D': '400', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'களிற்றியானை நிரை (120), மணிமிடை பவளம் (180), நித்திலக்கோவை (100).', 'topic': 'இலக்கியம் - அகநானூறு'}, {'question': '‘யாதும் ஊரே யாவரும் கேளிர்’ – என்ற வரி இடம்பெற்ற நூல் :', 'options': {'A': 'புறநானூறு', 'B': 'அகநானூறு', 'C': 'நற்றிணை', 'D': 'குறுந்தொகை', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'கணியன் பூங்குன்றனார் பாடிய புறநானூற்றுப் பாடல் இது.', 'topic': 'இலக்கியம் - புறநானூறு'}, {'question': 'கலித்தொகை நூலைத் தொகுத்த சங்கப் புலவர் யார்?', 'options': {'A': 'நல்லந்துவனார்', 'B': 'உக்கிரப் பெருவழுதி', 'C': 'பூரிக்கோ', 'D': 'நக்கீரர்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'துள்ளல் ஓசை கொண்ட கலிப்பாக்களால் ஆன கலித்தொகையைத் தொகுத்தவர் நெய்தற்கலி பாடிய நல்லந்துவனார் ஆவார்.', 'topic': 'இலக்கியம் - எட்டுத்தொகை'}, {'question': 'நெடுநல்வாடையின் பாட்டுடைத் தலைவன் யார்?', 'options': {'A': 'பாண்டியன் நெடுஞ்செழியன்', 'B': 'கரிகாலன்', 'C': 'செங்குட்டுவன்', 'D': 'இளந்திரையன்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'தலையாலங்கானத்துச் செருவென்ற பாண்டியன் நெடுஞ்செழியனை நக்கீரர் பாடியுள்ளார்.', 'topic': 'இலக்கியம் - பத்துப்பாட்டு'}, {'question': 'தேவாரம் பாடிய மூவருள் இளையவர் யார்?', 'options': {'A': 'திருஞானசம்பந்தர்', 'B': 'திருநாவுக்கரசர்', 'C': 'சுந்தரர்', 'D': 'மாணிக்கவாசகர்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'தன் 16-வது வயதிலேயே முக்தி அடைந்த திருஞானசம்பந்தர் வயதால் இளையவர்.', 'topic': 'இலக்கியம் - தேவாரம்'}, {'question': '‘திருவாசகம்’ எத்தனையாவது திருமுறையாகத் தொகுக்கப்பட்டுள்ளது?', 'options': {'A': 'எட்டாம் திருமுறை', 'B': 'ஏழாம் திருமுறை', 'C': 'ஒன்பதாம் திருமுறை', 'D': 'பன்னிரண்டாம் திருமுறை', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'மாணிக்கவாசகர் அருளிய திருவாசகமும் திருக்கோவையாரும் எட்டாம் திருமுறையாகும்.', 'topic': 'இலக்கியம் - திருவாசகம்'}, {'question': 'பெரியபுராணத்தில் பாடப்பெற்ற அடியார்கள் எத்தனை பேர்?', 'options': {'A': '63 தனி அடியார்கள் மற்றும் 9 தொகை அடியார்கள்', 'B': '100 பேர்', 'C': '12 ஆழ்வார்கள்', 'D': '4 மூவர்கள்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'சேக்கிழார் அறுபத்து மூன்று தனி அடியார்களையும் ஒன்பது தொகை அடியார்களையும் பாடியுள்ளார்.', 'topic': 'இலக்கியம் - பெரியபுராணம்'}, {'question': 'குற்றாலக் குறவஞ்சி எந்த ஊரில் உள்ள இறைவனைப் பாடுகிறது?', 'options': {'A': 'திருக்குற்றாலம்', 'B': 'மதுரை', 'C': 'திருநெல்வேலி', 'D': 'கும்பகோணம்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'தென்காசிக்கு அருகிலுள்ள திருக்குற்றாலத் தலத்துக் குறும்பலா நாதரைப் பாடுவது.', 'topic': 'இலக்கியம் - குற்றாலக் குறவஞ்சி'}, {'question': 'கலிங்கத்துப் பரணியின் ஆசிரியர் யார்?', 'options': {'A': 'செயங்கொண்டார்', 'B': 'ஒட்டக்கூத்தர்', 'C': 'புகழேந்தி', 'D': 'கம்பர்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'முதலாம் குலோத்துங்க சோழனின் தளபதி கருணாகரத் தொண்டைமானின் வெற்றியைச் செயங்கொண்டார் பாடினார்.', 'topic': 'இலக்கியம் - கலிங்கத்துப் பரணி'}, {'question': 'தமிழ்விடு தூது நூலில் அமைந்துள்ள கண்ணிகள் எத்தனை?', 'options': {'A': '268', 'B': '100', 'C': '300', 'D': '150', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'மதுரை சொக்கநாதரிடம் தூது அனுப்பும் இந்நூல் 268 கண்ணிகளைக் கொண்டது.', 'topic': 'இலக்கியம் - தமிழ்விடு தூது'}, {'question': 'முக்கூடற்பள்ளு நூலில் கூறப்படும் முக்கூடல் நகரம் எங்குள்ளது?', 'options': {'A': 'திருநெல்வேலி மாவட்டம்', 'B': 'மதுரை மாவட்டம்', 'C': 'தஞ்சாவூர் மாவட்டம்', 'D': 'திருச்சி மாவட்டம்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'தாமிரபரணி ஆறும் சிற்றாறும் கூடும் திருநெல்வேலி மாவட்ட முக்கூடல் தலம்.', 'topic': 'இலக்கியம் - முக்கூடற்பள்ளு'}, {'question': 'சீறாப்புராணத்தின் ஆசிரியர் யார்?', 'options': {'A': 'உமறுப்புலவர்', 'B': 'செய்குத்தம்பி பாவலர்', 'C': 'குணங்குடி மஸ்தான்', 'D': 'ஜவ்வாதுப் புலவர்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'நபிகள் நாயகத்தின் சீரிய வரலாற்றைப் பாடியவர் எட்டயபுரத்து உமறுப்புலவர்.', 'topic': 'இலக்கியம் - சீறாப்புராணம்'}, {'question': 'தேம்பாவணியின் ஆசிரியர் யார்?', 'options': {'A': 'வீரமாமுனிவர்', 'B': 'ஜி.யு. போப்', 'C': 'கால்டுவெல்', 'D': 'எச்.ஏ. கிருஷ்ணபிள்ளை', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'இத்தாலியத் துறவி கான்ஸ்டன்டைன் ஜோசப் பெஸ்கி (வீரமாமுனிவர்) இயற்றினார்.', 'topic': 'இலக்கியம் - தேம்பாவணி'}, {'question': '‘ஒன்றே குலமும் ஒருவனே தேவனும்’ – என்று பாடியவர் யார்?', 'options': {'A': 'திருமூலர்', 'B': 'பட்டினத்தார்', 'C': 'சிவவாக்கியார்', 'D': 'வள்ளலார்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'திருமந்திரத்தில் மனித குல ஒற்றுமையையும் கடவுள் ஒருமைப்பாட்டையும் திருமூலர் பாடியுள்ளார்.', 'topic': 'இலக்கியம் - திருமந்திரம்'}, {'question': '‘நட்டகல்லும் பேசுமோ நாதன் உள் இருக்கையில்’ – என்று பாடிய சித்தர் :', 'options': {'A': 'சிவவாக்கியார்', 'B': 'திருமூலர்', 'C': 'பட்டினத்தார்', 'D': 'போகர்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'உருவ வழிபாட்டின் போலித்தனத்தைக் கண்டித்துப் பாடிய சித்தர் சிவவாக்கியார்.', 'topic': 'இலக்கியம் - சித்தர் பாடல்கள்'}, {'question': '‘அருட்பெருஞ்ஜோதி தனிப்பெருங்கருணை’ – என்று முழங்கியவர் யார்?', 'options': {'A': 'இராமலிங்க அடிகளார் (வள்ளலார்)', 'B': 'தாயுமானவர்', 'C': 'பட்டினத்தார்', 'D': 'திருமூலர்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'வடலூரில் ஜோதி வழிபாட்டைத் தொடங்கி வைத்த வள்ளலாரின் தாரக மந்திரம் இது.', 'topic': 'இலக்கியம் - திருவருட்பா'}, {'question': '‘யாமறிந்த மொழிகளிலே தமிழ்மொழி போல் இனிதாவது எங்கும் காணோம்’ – என்று பாடியவர் :', 'options': {'A': 'மகாகவி பாரதியார்', 'B': 'பாரதிதாசன்', 'C': 'நாமக்கல் கவிஞர்', 'D': 'கவிமணி', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'பல்வேறு மொழிகளைக் கற்றறிந்த மகாகவி பாரதியார் தமிழின் இனிமையைப் போற்றிப் பாடிய வரிகள்.', 'topic': 'தமிழ் அறிஞர்கள் - பாரதியார்'}, {'question': 'பாரதியாரின் ‘கண்ணன் பாட்டு’ மற்றும் ‘குயில் பாட்டு’ ஆகியவை எவ்வகை நூல்கள்?', 'options': {'A': 'கவிதை நூல்கள்', 'B': 'உரைநடை நூல்கள்', 'C': 'நாடக நூல்கள்', 'D': 'ஆராய்ச்சி நூல்கள்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'பாரதியாரின் கற்பனை நயமும் தத்துவக் கருத்துகளும் மிளிரும் அமர கவிதைப் படைப்புகள்.', 'topic': 'தமிழ் அறிஞர்கள் - பாரதியார்'}, {'question': '‘தமிழுக்கு நிலவென்று பேர் – இன்பத் தமிழ் எங்கள் சமுகத்தின் விளைவுக்கு நீர்’ – என்று பாடியவர் :', 'options': {'A': 'பாரதிதாசன்', 'B': 'பாரதியார்', 'C': 'வாணிதாசன்', 'D': 'முடியரசன்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'சமூக வளர்ச்சிக்கு நீர் போல இன்பத் தமிழ் அவசியமானது எனப் பாவேந்தர் பாடியுள்ளார்.', 'topic': 'தமிழ் அறிஞர்கள் - பாரதிதாசன்'}, {'question': 'பாரதிதாசனுக்குத் தமிழக அரசு அமைத்த நினைவகம் எங்குள்ளது?', 'options': {'A': 'புதுச்சேரி (பெருமாள் கோவில் தெரு)', 'B': 'சென்னை', 'C': 'மதுரை', 'D': 'எட்டயபுரம்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'புதுச்சேரியில் பாவேந்தர் வாழ்ந்த இல்லம் புதுவை அரசால் நினைவகமாகப் பாதுகாக்கப்படுகிறது.', 'topic': 'தமிழ் அறிஞர்கள் - பாரதிதாசன்'}, {'question': 'நாமக்கல் கவிஞருக்கு நடுவண் அரசு வழங்கிய உயரிய விருது எது?', 'options': {'A': 'பத்ம பூஷண் (1971)', 'B': 'பாரத ரத்னா', 'C': 'பத்மஸ்ரீ', 'D': 'ஞானபீட விருது', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'விடுதலைப் போராட்ட வீரரும் கவிஞருமான நாமக்கல் கவிஞருக்கு இந்திய அரசு பத்ம பூஷண் விருது வழங்கியது.', 'topic': 'தமிழ் அறிஞர்கள் - நாமக்கல் கவிஞர்'}, {'question': 'கவிமணி தேசிக விநாயகம் பிள்ளைக்கு ‘கவிமணி’ என்ற பட்டத்தை வழங்கிய அமைப்பு எது?', 'options': {'A': 'சென்னைத் தமிழ்ச் சங்கம் (உமாமகேசுவரனார் தலைமையில்)', 'B': 'மதுரைத் தமிழ்ச் சங்கம்', 'C': 'புதுவைத் தமிழ்ச் சங்கம்', 'D': 'கரந்தைத் தமிழ்ச் சங்கம்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': "1940-இல் சென்னை பச்சையப்பன் கல்லூரியில் நடைபெற்ற விழாவில் உமாமகேசுவரனாரால் 'கவிமணி' பட்டம் வழங்கப்பட்டது.", 'topic': 'தமிழ் அறிஞர்கள் - கவிமணி'}, {'question': 'கவிஞர் முடியரசனின் இயற்பெயர் யாது?', 'options': {'A': 'துரைராசு', 'B': 'முத்தையா', 'C': 'எத்திராசலு', 'D': 'சுப்புரத்தினம்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'காரைக்குடியில் தமிழாசிரியராகப் பணியாற்றிய கவிஞர் முடியரசனின் இயற்பெயர் துரைராசு.', 'topic': 'தமிழ் அறிஞர்கள் - முடியரசன்'}, {'question': 'கவிஞர் வாணிதாசன் எழுதிய குழந்தை இலக்கிய நூல் எது?', 'options': {'A': 'குழந்தைப் பாட்டு', 'B': 'மழலை மலர்', 'C': 'பாப்பா பாட்டு', 'D': 'சிறுவர் பாடல்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': "குழந்தைகளுக்கான இனிய சந்தப் பாடல்களைக் கொண்ட நூல் 'குழந்தைப் பாட்டு'.", 'topic': 'தமிழ் அறிஞர்கள் - வாணிதாசன்'}, {'question': 'உவமைக் கவிஞர் சுரதா பிறந்த ஊர் எது?', 'options': {'A': 'பழையனூர் (திருவாரூர் மாவட்டம்)', 'B': 'எட்டயபுரம்', 'C': 'வில்லியனூர்', 'D': 'சிறுகூடல்பட்டி', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'நாகப்பட்டினம்/திருவாரூர் மாவட்டத்திலுள்ள பழையனூரில் திருவேங்கடம் - செண்பகம் இணையருக்கு மகனாகப் பிறந்தார்.', 'topic': 'தமிழ் அறிஞர்கள் - சுரதா'}, {'question': 'கண்ணதாசன் திரைப்படத் துறைக்கு எழுதிய முதல் பாடல் இடம்பெற்ற திரைப்படம் எது?', 'options': {'A': 'கன்னியின் காதலி (1949)', 'B': 'பராசக்தி', 'C': 'மலைக்கள்ளன்', 'D': 'கப்பலோட்டிய தமிழன்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': "'கலங்காதிரு மனமே' என்ற பாடலை 1949-இல் கன்னியின் காதலி படத்திற்காகக் கண்ணதாசன் முதன்முதலில் எழுதினார்.", 'topic': 'தமிழ் அறிஞர்கள் - கண்ணதாசன்'}, {'question': 'பட்டுக்கோட்டை கல்யாணசுந்தரம் மறைந்த வயது யாது?', 'options': {'A': '29 வயது', 'B': '35 வயது', 'C': '40 வயது', 'D': '50 வயது', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'மக்கள் மனங்களில் அழியாத இடம்பெற்ற மக்கள் கவிஞர் தன் 29-வது இளம் வயதிலேயே காலமானார்.', 'topic': 'தமிழ் அறிஞர்கள் - பட்டுக்கோட்டை கல்யாணசுந்தரம்'}, {'question': 'ந. பிச்சமூர்த்தி வழக்கறிஞராகவும் பின்னர் எந்தத் துறையில் அலுவலராகவும் பணியாற்றினார்?', 'options': {'A': 'இந்து சமய அறநிலையத்துறை (கோயில் நிர்வாக அலுவலர்)', 'B': 'காவல்துறை', 'C': 'வருவாய்த்துறை', 'D': 'கல்வித்துறை', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'வழக்கறிஞர் தொழிலுக்குப் பின் கோயில் நிர்வாக அதிகாரியாக ந. பிச்சமூர்த்தி பல ஆண்டுகள் பணியாற்றினார்.', 'topic': 'தமிழ் அறிஞர்கள் - ந. பிச்சமூர்த்தி'}, {'question': '‘நிலவுப்பூ’ என்ற கவிதை நூலின் ஆசிரியர் யார்?', 'options': {'A': 'சிற்பி பாலசுப்பிரமணியம்', 'B': 'மு. மேத்தா', 'C': 'அப்துல் ரகுமான்', 'D': 'வைரமுத்து', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': "பாரதியார் பல்கலைக்கழகத் தமிழ்த்துறைத் தலைவராக விளங்கிய சிற்பி பாலசுப்பிரமணியத்தின் கவிதை நூல் 'நிலவுப்பூ'.", 'topic': 'தமிழ் அறிஞர்கள் - சிற்பி பாலசுப்பிரமணியம்'}, {'question': "‘சுயசரிதை’ வடிவில் ஆங்கிலத்தில் ‘India's Freedom’ குறித்த நூல்களை எழுதியவர் :", 'options': {'A': 'நேரு', 'B': 'பாரதியார்', 'C': 'திரு.வி.க.', 'D': 'வ.உ.சி.', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'ஜவாஹர்லால் நேரு இந்திரா காந்திக்கு எழுதிய கடிதங்களும் சுயசரிதையும் உலகப் புகழ்பெற்றவை.', 'topic': 'கடித இலக்கியம்'}, {'question': 'பரிதிமாற்கலைஞர் இயற்றிய தனிப்பாசுரத் தொகை என்ற நூலை ஆங்கிலத்தில் மொழிபெயர்த்தவர் யார்?', 'options': {'A': 'ஜி.யு. போப்', 'B': 'கால்டுவெல்', 'C': 'வீரமாமுனிவர்', 'D': 'எல்லீஸ்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'பரிதிமாற்கலைஞரின் பா நயத்தைப் பாராட்டி ஜி.யு. போப் அவரது தனிப்பாசுரத் தொகையை ஆங்கிலத்தில் மொழிபெயர்த்தார்.', 'topic': 'தமிழ் அறிஞர்கள் - பரிதிமாற்கலைஞர்'}, {'question': '‘தனித்தமிழ் இயக்கம்’ தொடங்கப்பட்ட ஆண்டு எது?', 'options': {'A': '1916', 'B': '1920', 'C': '1905', 'D': '1925', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'மறைமலையடிகளாரும் அவரது மகள் நீலாம்பிகை அம்மையாரும் 1916-இல் தனித்தமிழ் இயக்கத்தைத் தொடங்கினர்.', 'topic': 'தமிழ் அறிஞர்கள் - மறைமலையடிகள்'}, {'question': 'திரு.வி.க. அவர்களின் முழுப் பெயர் யாது?', 'options': {'A': 'திருவாரூர் விருத்தாசலம் கல்யாணசுந்தரனார்', 'B': 'திருவாவடுதுறை கல்யாணசுந்தரம்', 'C': 'திருவல்லிக்கேணி கல்யாணசுந்தரம்', 'D': 'திருச்சி கல்யாணசுந்தரம்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'தந்தை விருத்தாசலனார், சொந்த ஊர் திருவாரூர்; திரு.வி. கல்யாணசுந்தரனார் என்பது முழுப்பெயர்.', 'topic': 'தமிழ் அறிஞர்கள் - திரு.வி.க.'}, {'question': 'வ.உ.சிதம்பரனார் பிறந்த மாவட்டம் எது?', 'options': {'A': 'தூத்துக்குடி மாவட்டம் (ஒட்டப்பிடாரம்)', 'B': 'திருநெல்வேலி', 'C': 'மதுரை', 'D': 'கன்னியாகுமரி', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'ஒட்டப்பிடாரத்தில் உலகநாத பிள்ளை - பரமாயி அம்மையாருக்கு மகனாக வ.உ.சி பிறந்தார்.', 'topic': 'தமிழ் அறிஞர்கள் - வ.உ.சி.'}, {'question': 'உ.வே.சா. அவர்களின் உருவச்சிலை எந்தக் கல்லூரியின் வளாகத்தில் நிறுவப்பட்டுள்ளது?', 'options': {'A': 'சென்னை மாநிலக் கல்லூரி (Presidency College)', 'B': 'பச்சையப்பன் கல்லூரி', 'C': 'மதுரை தியாகராசர் கல்லூரி', 'D': 'அண்ணாமலைப் பல்கலைக்கழகம்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'உ.வே.சா பேராசிரியராகப் பணியாற்றிய சென்னை மாநிலக் கல்லூரியின் மெரினா கடற்கரை முகப்பில் அவரது சிலை அமைக்கப்பட்டுள்ளது.', 'topic': 'தமிழ் அறிஞர்கள் - உ.வே.சா.'}, {'question': 'தேவநேயப்பாவாணரின் ஆராய்ச்சி நூல்களுள் தலையாயது எது?', 'options': {'A': 'செந்தமிழ்ச் சொற்பிறப்பியல் பேரகரமுதலி', 'B': 'தமிழின்பம்', 'C': 'என் சரிதம்', 'D': 'பெண்ணின் பெருமை', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'தமிழ் வேர்ச்சொற்களை ஆய்வு செய்து பல்லாயிரக்கணக்கான பக்கங்களில் பாவாணர் அமைத்த பேரகரமுதலி.', 'topic': 'தமிழ் அறிஞர்கள் - தேவநேயப்பாவாணர்'}, {'question': 'வீரமாமுனிவர் இயற்றிய இலக்கண நூல் எது?', 'options': {'A': 'தொன்னூல் விளக்கம் (குட்டித் தொல்காப்பியம்)', 'B': 'நன்னூல்', 'C': 'தண்டியலங்காரம்', 'D': 'வீரசோழியம்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': "எழுத்து, சொல், பொருள், யாப்பு, அணி ஆகிய ஐந்து இலக்கணங்களையும் கூறும் 'தொன்னூல் விளக்கம்' வீரமாமுனிவரின் படைப்பு.", 'topic': 'அயல்நாட்டுத் தமிழறிஞர்கள் - வீரமாமுனிவர்'}, {'question': 'கால்டுவெல் எந்த நாட்டைச் சார்ந்த கிறித்தவப் பாதிரியார்?', 'options': {'A': 'அயர்லாந்து (Ireland)', 'B': 'இத்தாலி', 'C': 'இங்கிலாந்து', 'D': 'ஜெர்மனி', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'ராபர்ட் கால்டுவெல் அயர்லாந்தில் பிறந்து திருநெல்வேலி இடையன்குடியில் தங்கித் தமிழ்ப் பணி புரிந்தார்.', 'topic': 'அயல்நாட்டுத் தமிழறிஞர்கள் - கால்டுவெல்'}, {'question': 'தந்தை பெரியார் குடியரசு இதழைத் தொடங்கிய ஆண்டு எது?', 'options': {'A': '1925 (மே 2)', 'B': '1920', 'C': '1930', 'D': '1935', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': '1925 மே மாதம் 2-ஆம் தேதி சுயமரியாதைக் கருத்துகளுக்காக குடியரசு இதழ் தொடங்கப்பட்டது.', 'topic': 'சமுதாயத் தலைவர்கள் - தந்தை பெரியார்'}, {'question': 'பெருந்தலைவர் காமராசர் எங்கு பிறந்தார்?', 'options': {'A': 'விருதுநகர் (விருதுபட்டி)', 'B': 'மதுரை', 'C': 'திருநெல்வேலி', 'D': 'தூத்துக்குடி', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'குமாரசாமி நாடார் - சிவகாமி அம்மையாருக்கு மகனாக விருதுநகரில் காமராசர் பிறந்தார்.', 'topic': 'சமுதாயத் தலைவர்கள் - காமராசர்'}, {'question': 'வேலுநாச்சியார் எந்த மன்னரின் மகள்?', 'options': {'A': 'இராமநாதபுரம் செல்லமுத்து விஜயரகுநாத சேதுபதி', 'B': 'முத்துவடுகநாதர்', 'C': 'மருது பாண்டியர்', 'D': 'கட்டபொம்மன்', 'E': 'விடை தெரியவில்லை'}, 'answer': 'A', 'explanation': 'சேதுபதி மன்னர் செல்லமுத்துவுக்கு ஒரே மகளாகப் பிறந்து சிவகங்கை முத்துவடுகநாதரை மணந்தவர் வேலுநாச்சியார்.', 'topic': 'விடுதலைப் போராட்டத்தில் தமிழகப் பெண்கள்'}]
